from pathlib import Path
import hashlib
import json
import sqlite3


RISK_SYSTEM = "riskonnect_risk_register"
PLA_SYSTEM = "pla_marine_interface"
PROJECT_ID = "PRJ-TTT-CRR-001"

OTHER_PROJECT_RISKS_HASH = "069ab62f2e6e314633e70e9235eba55bb4960eac3395528c490c0df2af4294c5"
CORY_OPERATIONS_HASH = "796e0472952a9ffe91b7aae3114f244eaa4c7482350d3a2ed4ce88ccc690324a"

SOURCE_HASHES = {
    "01_Source_Extracts/caltrans_quantitative_risk_practices.pdf": "0e48f33c1c12283bd83d6658d5d254cc059417c2a6782af89e5905b94023ba4d",
    "01_Source_Extracts/carnwath_hazard_log_extract.csv": "20fa2b0146ac151d3a448a742e0eb921b4c445fc2cad51e0d723e84194139c2c",
    "01_Source_Extracts/deep_excavation_cost_schedule_inputs.csv": "ccea891de40b89defc75b52ed983724d0f6a397ee27a4b7b80f428a3475698a2",
