def _db_path(workspace, system):
    return Path(workspace).resolve().parent / "system" / system / "state.db"


def _rows(workspace, system, sql, params=()):
    connection = sqlite3.connect(f"file:{_db_path(workspace, system)}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(sql, tuple(params)).fetchall()]
    finally:
        connection.close()


def _logical_hash(rows):
    payload = json.dumps(rows, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _norm(value):
    return " ".join(str(value or "").split()).casefold()


def _target(workspace):
    rows = _rows(workspace, RISK_SYSTEM, "SELECT * FROM risk_register WHERE risk_id = ?", ("R-03",))
    return rows[0] if len(rows) == 1 else None


def check_target_owner_and_approver(workspace):
    row = _target(workspace)
    if row is None:
        return {"score": 0, "detail": "Riskonnect R-03 is missing or duplicated."}
    expected = {
        "owner_person_id": "PER-OGRANT-001",
        "owner_name": "oliver grant",
        "approver_person_id": "PER-DHUGHES-004",
        "approver_name": "daniel hughes",
    }
    actual = {
        "owner_person_id": row.get("owner_person_id"),
        "owner_name": _norm(row.get("owner_name")),
        "approver_person_id": row.get("approver_person_id"),
        "approver_name": _norm(row.get("approver_name")),
    }
    if actual != expected:
        return {"score": 0, "detail": f"R-03 ownership/approval mismatch: {actual}"}
    return {"score": 1, "detail": "R-03 is owned by Oliver Grant and retains Daniel Hughes as approver."}


def check_effective_date_version_and_history(workspace):
    row = _target(workspace)
    if row is None:
        return {"score": 0, "detail": "Riskonnect R-03 is missing or duplicated."}
    try:
        history = json.loads(row.get("ownership_history_json") or "[]")
    except (TypeError, json.JSONDecodeError):
        return {"score": 0, "detail": "R-03 ownership history is not valid JSON."}
    original = {
        "effective_at": "2025-01-13T10:20:00Z",
        "owner_person_id": "PER-SCHEN-001",
        "approver_person_id": "PER-DHUGHES-004",
        "reason": "Assigned following interface workshop",
    }
    date_ok = str(row.get("owner_changed_at") or "")[:10] == "2025-09-18"
    final = history[-1] if history else {}
    final_ok = (
        str(final.get("effective_at") or "")[:10] == "2025-09-18"
        and final.get("owner_person_id") == "PER-OGRANT-001"
        and final.get("approver_person_id") == "PER-DHUGHES-004"
    )
    if not (date_ok and row.get("row_version") == 4 and len(history) == 2 and history[0] == original and final_ok):
        return {
            "score": 0,
            "detail": f"Expected date 2025-09-18, version 4, and one appended history entry; got date={row.get('owner_changed_at')}, version={row.get('row_version')}, history={history}",
        }
    return {"score": 1, "detail": "Effective date, optimistic-lock version increment, and append-only history are correct."}


def check_controlled_change_rationale(workspace):
    row = _target(workspace)
    if row is None:
        return {"score": 0, "detail": "Riskonnect R-03 is missing or duplicated."}
    try:
        history = json.loads(row.get("ownership_history_json") or "[]")
    except (TypeError, json.JSONDecodeError):
        return {"score": 0, "detail": "R-03 ownership history is not valid JSON."}
    reason = _norm(row.get("owner_change_reason"))
    history_reason = _norm(history[-1].get("reason")) if history else ""
    semantic_ok = (
        "workshop" in reason
        and "cory" in reason
        and any(token in reason for token in ("owner", "ownership", "accountab", "align"))
    )
    if not reason or reason != history_reason or not semantic_ok:
        return {"score": 0, "detail": "The current and appended reasons must match and reference the workshop, Cory, and ownership alignment."}
    return {"score": 1, "detail": "The controlled ownership rationale is consistent and semantically complete."}


def check_other_project_risks_unchanged(workspace):
    rows = _rows(
        workspace,
        RISK_SYSTEM,
        "SELECT * FROM risk_register WHERE project_id = ? AND risk_id <> ? ORDER BY risk_id",
        (PROJECT_ID, "R-03"),
    )
    if len(rows) != 3 or _logical_hash(rows) != OTHER_PROJECT_RISKS_HASH:
        return {"score": 0, "detail": "A non-target Carnwath project risk was changed, inserted, or deleted."}
    return {"score": 1, "detail": "All non-target Carnwath project risk rows are unchanged."}


def check_source_evidence_unchanged(workspace):
    workspace = Path(workspace)
    changed = []
    for relative_path, expected_hash in SOURCE_HASHES.items():
        path = workspace / relative_path
        if not path.is_file():
            changed.append(f"missing: {relative_path}")
        elif hashlib.sha256(path.read_bytes()).hexdigest() != expected_hash:
            changed.append(f"modified: {relative_path}")
    cory_operations = _rows(
        workspace,
        PLA_SYSTEM,
        "SELECT * FROM marine_operations WHERE counterparty_org_id = ? ORDER BY operation_id",
        ("ORG-CORY-001",),
    )
    if len(cory_operations) != 3 or _logical_hash(cory_operations) != CORY_OPERATIONS_HASH:
        changed.append("modified: Port of London Authority Cory marine operations")
    if changed:
        return {"score": 0, "detail": "; ".join(changed)}
    return {"score": 1, "detail": "Workspace evidence and canonical Cory marine-operation rows are unchanged."}
